function kind(v) {
  return typeof v === "object" && v !== null ? v.constructor.name : typeof v;
}

function lostKeys(value) {
  const back = JSON.parse(JSON.stringify(value));
  return Object.keys(value).filter((key) => kind(value[key]) !== kind(back[key]));
}

