import { JSONSerializer } from "@zudojs/serialization";

class Duration {
  constructor(minutes) {
    this.minutes = minutes;
  }
}

const DurationTransformer = {
  type: "Duration",
  canSerialize: (value) => value instanceof Duration,
  serialize: (value) => ({ $type: "Duration", $value: value.minutes }),
  deserialize: (value) => {
    const minutes = value.$value;
    if (typeof minutes !== "number" || !Number.isInteger(minutes) || minutes < 0) {
      throw new TypeError("A Duration needs a whole number of minutes");
    }
    return new Duration(minutes);
  },
};

const serializer = new JSONSerializer({ defaults: { preserveTypes: true } });
serializer.registerTransformer(DurationTransformer);
const text = serializer.serialize({ estimate: new Duration(90) });
console.log(text); // {"estimate":{"$type":"Duration","$value":90}}
const back = serializer.deserialize(text);
console.log(back.estimate instanceof Duration, back.estimate.minutes); // true 90

