function tag(obj) {
  const out = {};
  for (const [key, value] of Object.entries(obj)) {
    if (value instanceof Date) out[key] = { $type: "Date", $value: value.toISOString() };
    else if (value instanceof Set) out[key] = { $type: "Set", $value: [...value] };
    else out[key] = value;
  }
  return out;
}

const task = { id: 1, due: new Date("2026-10-05T09:00:00Z"), tags: new Set(["home"]) };
console.log(JSON.stringify(tag(task)));
// {"id":1,"due":{"$type":"Date","$value":"2026-10-05T09:00:00.000Z"},"tags":{"$type":"Set","$value":["home"]}}
